"% Trim solver for nonlinear climb + coordinated turn
% Three coupled equations in three unknowns: alpha, T, delta_e
W = 200000.0;       % lbf
S = 2100.0;         % ft^2
h = 27000.0;        % ft
V = 700.0;          % ft/s
gamma_deg = 4.0;
phi_deg = 25.0;
gamma = deg2rad(gamma_deg);
phi = deg2rad(phi_deg);

% Aerodynamic coefficients
CL0 = 0.12;
CLa = 4.9;          % per rad
CLde = 0.4;         % per rad
CD0 = 0.023;
k = 0.041;

% Atmosphere
rho0 = 0.0023769;   % slug/ft^3
rho = rho0 * exp(-h/23800);
q = 0.5 * rho * V^2;

% Thrust installation
i_T_deg = 2.0;
i_T = deg2rad(i_T_deg);
z_T = 1.8;          % ft

% Pitching coefficients
Cm0 = 0.018;
Cmalpha = -0.28;    % per rad
Cmdelta_e = -0.8;   % per rad
cbar = 16.0;        % ft

% Initial guess: alpha=5 deg, T=28000 lbf, delta_e=-0.5 deg
x = [deg2rad(5.0); 28000.0; deg2rad(-0.5)];

% Damped Newton iteration with analytical Jacobian
for iter = 1:200
    a = x(1);
    T = x(2);
    de = x(3);
    CL = CL0 + CLa*a + CLde*de;
    CD = CD0 + k*CL^2;

    % Residual vector
    f = zeros(3,1);
    f(1) = q*S*CL*cos(phi) + T*sin(a + i_T) - W*cos(gamma);
    f(2) = T*cos(a + i_T) - q*S*CD - W*sin(gamma);
    f(3) = q*S*cbar*(Cm0 + Cmalpha*a + Cmdelta_e*de) + T*sin(i_T)*z_T;

    % Analytical Jacobian
    J = zeros(3,3);
    J(1,1) = q*S*CLa*cos(phi) + T*cos(a + i_T);
    J(1,2) = sin(a + i_T);
    J(1,3) = q*S*CLde*cos(phi);

    J(2,1) = -T*sin(a + i_T) - q*S*2*k*CL*CLa;
    J(2,2) = cos(a + i_T);
    J(2,3) = -q*S*2*k*CL*CLde;

    J(3,1) = q*S*cbar*Cmalpha;
    J(3,2) = sin(i_T)*z_T;
    J(3,3) = q*S*cbar*Cmdelta_e;

    dx = -J\f;

    % Damped step (backtracking line search)
    lambda = 1.0;
    fnorm = norm(f);
    x_new = x;
    for sub = 1:30
        x_try = x + lambda*dx;
        a_t = x_try(1); T_t = x_try(2); de_t = x_try(3);
        CL_t = CL0 + CLa*a_t + CLde*de_t;
        CD_t = CD0 + k*CL_t^2;
        f1_t = q*S*CL_t*cos(phi) + T_t*sin(a_t + i_T) - W*cos(gamma);
        f2_t = T_t*cos(a_t + i_T) - q*S*CD_t - W*sin(gamma);
        f3_t = q*S*cbar*(Cm0 + Cmalpha*a_t + Cmdelta_e*de_t) + T_t*sin(i_T)*z_T;
        fnorm_t = sqrt(f1_t^2 + f2_t^2 + f3_t^2);
        if fnorm_t < fnorm || lambda < 1e-8
            x_new = x_try;
            break;
        end
        lambda = lambda * 0.5;
    end
    x = x_new;

    if norm(dx) < 1e-12 && norm(f) < 1e-6
        break;
    end
end

alpha_trim_deg = rad2deg(x(1));
thrust_lbf = x(2);
delta_e_trim_deg = rad2deg(x(3));
load_factor = cos(gamma)/cos(phi);

result = struct('alpha_trim_deg', alpha_trim_deg, ...
                'thrust_lbf', thrust_lbf, ...
                'delta_e_trim_deg', delta_e_trim_deg, ...
                'load_factor', load_factor);

fid = fopen('result.json', 'w');
fwrite(fid, jsonencode(result));
fclose(fid);"
